head.script:
scwin.gVar = {
    "cOnFocusClass" : "",
    "cDisabled" : "",
    "cReadOnly" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > onFocusClass]<br/>Secret 컴포넌트가 포커스 되었을때 적용할 CSS 클래스를 설정합니다.",
    "validation" : [
        "CSS 파일이나 style 블럭에 정의된 클래스 이름을 공백으로 구분하여 설정합니다.",
        "값을 설정하지 않으면 'w2input_focus' 클래스가 적용됩니다.",
        "속성값을 설정하면 기본값인 'w2input_focus' 클래스는 적용되지 않습니다.",
        "컴포넌트가 포커스를 얻으면 설정한 CSS 클래스가 추가되고, 잃으면 적용된 CSS 클래스가 제거됩니다.",
        "CSS 클래스의 추가/제거는 onfocus/onblur 이벤트가 발생하기 전에 실행됩니다.",
        "컴포넌트가 비활성화(disabled) 또는 읽기 전용(readonly) 상태이면 해당 속성은 무시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    con_onFocusClass.setValue("onFocusClass");
    con_disabled.setValue("1");
    con_readOnly.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 onFocusClass, disabled, readOnly 는 위 조건에서 선택합니다 (onFocusClass 는 배경 노랑, evenClass 는 둥근 모서리로 tc.css 에 정의)\n[절차] 조건 선택 -> Target 재생성 -> target1 클릭하여 포커스 -> 바깥 영역 클릭하여 포커스 해제 (포커스 이벤트가 발생하지 않는 조건은 focus 버튼으로 확인)\n[확인] 결과창에 출력되는 시점별 class 문자열과 실제 적용된 배경색·테두리 (재생성 직후 / onfocus 핸들러 시점 / onblur 핸들러 시점 / focus() 직후)\n[참고] Secret 은 password 로 표시되어 값 확인이 어려우므로 class 문자열과 배경색·테두리로 판정하며, focus 버튼은 포커스 이벤트가 발생하지 않는 조건에서만 출력합니다"', '', 'label1');

    // 조건 설정
    scwin.gVar["cOnFocusClass"] = con_onFocusClass.getValue();
    scwin.gVar["cDisabled"] = con_disabled.getText();
    scwin.gVar["cReadOnly"] = con_readOnly.getText();

    let properties = {
        onFocusClass : scwin.gVar["cOnFocusClass"],
        disabled : scwin.gVar["cDisabled"],
        readOnly : scwin.gVar["cReadOnly"],
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onfocus", "onblur"]);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList, eList);

    // 포커스 전 기준 class (클래스 추가 여부 판정의 기준선) - validation 1 ~ 6 판정 출력
    scwin.printClass("재생성 직후");
}



// 시점별 class 문자열 출력 (판정 근거)
scwin.printClass = function (strWhen) {
    let strOnFocusClass = (scwin.gVar["cOnFocusClass"] === "") ? "미설정" : scwin.gVar["cOnFocusClass"];
    let strDisabled = (scwin.gVar["cDisabled"] === "") ? "미설정" : scwin.gVar["cDisabled"];
    let strReadOnly = (scwin.gVar["cReadOnly"] === "") ? "미설정" : scwin.gVar["cReadOnly"];

    // 미설정 케이스의 w2input_focus 는 프로젝트 CSS 에 규칙이 없어 배경색이 변하지 않으므로 border-color 도 함께 출력한다
    wf_body_bottom.getObj("scwin").setReturnValue("onFocusClass " + strOnFocusClass + " / disabled " + strDisabled + " / readOnly " + strReadOnly + " -> " + strWhen + " class : " + target1.render.className + " / bg : " + target1.getStyle("background-color") + " / border : " + target1.getStyle("border-color"));
}



// 테스트 샘플의 이벤트 처리 (포커스 획득) - validation 1 ~ 5 판정 출력
scwin.target1_onfocus = function (e) {
    scwin.bFocusFired = true;

    scwin.printClass("onfocus 핸들러 시점");
}



// 테스트 샘플의 이벤트 처리 (포커스 상실) - validation 4, 5 판정 출력
scwin.target1_onblur = function (e) {
    scwin.printClass("onblur 핸들러 시점");
}



// disabled / readOnly 조건은 포커스 이벤트가 발생하지 않아 핸들러 출력이 없으므로 포커스 부여 직후 class 로 판정 - validation 6 판정 출력
scwin.btn_focus_onclick = function (e) {
    scwin.bFocusFired = false;

    target1.focus();

    // onfocus 가 발생한 경우는 핸들러가 이미 같은 시점의 class 를 출력하므로 중복 출력하지 않는다
    if (!scwin.bFocusFired)
        scwin.printClass("focus() 직후 (onfocus 미발생)");
}
